import heapq

def solve(intervals):
    if not intervals:
        return 0
    intervals.sort()
    h1 = []
    for start, end in intervals:
        if h1 and h1[0] <= start:
            heapq.heappop(h1)
        heapq.heappush(h1, end)
    return len(h1)

