def solve(intervals):
    h4 = sorted((interval[0] for interval in intervals))
    h2 = sorted((interval[1] for interval in intervals))
    room_count = 0
    h1 = 0
    for h3 in h4:
        if h3 < h2[h1]:
            room_count += 1
        else:
            h1 += 1
    return room_count

