def solve(intervals):
    h1 = []
    for start, end in intervals:
        h1.append((start, 1))
        h1.append((end, -1))
    h1.sort()
    max_rooms = 0
    current_rooms = 0
    for time, delta in h1:
        current_rooms += delta
        if current_rooms > max_rooms:
            max_rooms = current_rooms
    return max_rooms

